#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-cloudflare (cloudflare-doctor) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Checks app.service acme::quiz::Quiz.site on Cloudflare against the model, for one environment, by name only:
# the deploy token and account id are in the vault; every secret the model declares is in the vault
# and on the Worker; wrangler.jsonc builds (`wrangler deploy --dry-run`); each domain answers.
# Exits 1 when a check fails. It prints names, never a value.
#
# Needs: keys-axi, jq, curl, and what deploy/cloudflare/wrangler.sh needs.
#
#   bash deploy/cloudflare/doctor.sh <environment>
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 2

ENVIRONMENT="${1:-}"
FAIL=0
ok() { echo "ok   $*"; }
bad() { echo "FAIL $*"; FAIL=1; }
KEYS_AXI="${KEYS_AXI:-$(command -v keys-axi || echo "$HOME/.local/bin/keys-axi")}"
[ -x "$KEYS_AXI" ] || { echo "doctor: keys-axi is not installed" >&2; exit 2; }
for tool in jq curl npx; do
  command -v "$tool" >/dev/null || { echo "doctor: $tool is not installed" >&2; exit 2; }
done

# in_vault <vault project> <vault environment> <NAME>...
in_vault() {
  local names
  names=$("$KEYS_AXI" ls --project "$1" --env "$2" --json | jq -r '.secrets[].name') || { bad "cannot list vault scope $1/$2"; return; }
  local where="$1/$2"; shift 2
  for n in "$@"; do
    if grep -qx "$n" <<<"$names"; then ok "$n is in the vault ($where)"; else bad "$n is not in the vault ($where)"; fi
  done
}

# on_cloudflare '<wrangler target arguments>' <NAME>...
on_cloudflare() {
  local names
  # shellcheck disable=SC2086 # the target arguments are words
  names=$(bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" secret list $1 --format json | jq -r '.[].name') || { bad "cannot list the Worker's secrets"; return; }
  shift
  for n in "$@"; do
    if grep -qx "$n" <<<"$names"; then ok "$n is set on the Worker"; else bad "$n is declared and not set on the Worker (run deploy/cloudflare/sync-secrets.sh)"; fi
  done
}

# builds '<wrangler target arguments>': the configuration and the Worker bundle build
builds() {
  local out
  out=$(mktemp -d)
  # shellcheck disable=SC2086 # the target arguments are words
  if bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" deploy --dry-run --outdir "$out" $1 >/dev/null 2>&1; then ok "wrangler.jsonc builds ($ENVIRONMENT)"; else bad "wrangler.jsonc does not build ($ENVIRONMENT): run wrangler deploy --dry-run to see why"; fi
  rm -rf "$out"
}

# answers <url>
answers() {
  if curl -fsS -o /dev/null --max-time 10 "$1"; then ok "$1 answers"; else bad "$1 does not answer 2xx"; fi
}

case "$ENVIRONMENT" in
  production)
    in_vault deploy dev CLOUDFLARE_WORKERS_TOKEN_QUIZ CLOUDFLARE_ACCOUNT_ID
    in_vault quiz prod SEARCH_URL
    on_cloudflare '--config wrangler.jsonc' SEARCH_URL
    builds '--config wrangler.jsonc'
    answers https://quiz.example.com/
    answers https://www.quiz.example.com/
    ;;
  staging)
    in_vault deploy dev CLOUDFLARE_WORKERS_TOKEN_QUIZ CLOUDFLARE_ACCOUNT_ID
    in_vault quiz staging SEARCH_URL
    on_cloudflare '--config wrangler.jsonc --env staging' SEARCH_URL
    builds '--config wrangler.jsonc --env staging'
    answers https://staging.quiz.example.com/
    ;;
  *) echo 'usage: bash deploy/cloudflare/doctor.sh <environment> (environments: production, staging)' >&2; exit 2 ;;
esac

exit "$FAIL"
